import{_ as n,c as p,o as e,b0 as l}from"./chunks/framework.Dmsv_Tiv.js";const i="/media-docs/assets/image-20240725074043718.B7Tv3tv8.png",r="/media-docs/assets/image-20240725074226505.C3MPfurL.png",c="/media-docs/assets/image-20240725074328368.BEZbhlSj.png",t="data:image/jpeg;base64,",o="/media-docs/assets/image-20240725075107599.BCmgkfu2.png",a="data:image/png;base64,",b="/media-docs/assets/image-20240726074942254.BV6Vo2R7.png",m="/media-docs/assets/image-20240727093445827.BQ8S39pZ.png",d="/media-docs/assets/image-20240727091512156.Dhp30xCc.png",u="/media-docs/assets/image-20240727093516502.ClDPwxKZ.png",A="/media-docs/assets/image-20240729075256730.CrNqW-JK.png",h="/media-docs/assets/image-20240727104257900.Dt5-K6uM.png",g="/media-docs/assets/image-20240727093046246.BVNNiIeF.png",F="/media-docs/assets/image-20240727105201634.BPklNq1t.png",P="/media-docs/assets/image-20240727105617732.DdJ4CUkM.png",C="/media-docs/assets/image-20240728093412783.DBKD6UaU.png",f="/media-docs/assets/image-20240728093813473.BnlfTI4O.png",D="/media-docs/assets/image-20240728095450833.CvYYD9qo.png",E="/media-docs/assets/image-20240728101513739.BuMDQXif.png",I="/media-docs/assets/image-20240728101645437.Dv08vT9A.png",J="/media-docs/assets/image-20240728101719062.BWQIjCtj.png",T="/media-docs/assets/image-20240728102229429.BkgdRPTx.png",k="/media-docs/assets/image-20240730073730286.CyR4XgXk.png",_=JSON.parse('{"title":"LV030-JPEG协议简介","description":null,"frontmatter":{"title":"LV030-JPEG协议简介","date":"2025-10-09T14:41:04.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/image/img-file-format/126b0e34d5280b27d8a08648","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2025-10-09T14:41:04.178Z","fulluuid":"7d8a08648b6d4ba2a8cf6f6588b789e4","useduuid":"7d8a08648"}},"headers":[],"relativePath":"sdoc/image/img-file-format/126b0e34d5280b27d8a08648.md","filePath":"sdoc/01-图像/30-图像文件格式/LV030-JPEG协议简介.md","lastUpdated":1767537778000}'),G={name:"sdoc/image/img-file-format/126b0e34d5280b27d8a08648.md"};function Q(R,s,x,q,S,v){return e(),p("div",null,[...s[0]||(s[0]=[l('<h1 id="lv030-jpeg协议简介" tabindex="-1">LV030-JPEG协议简介 <a class="header-anchor" href="#lv030-jpeg协议简介" aria-label="Permalink to &quot;LV030-JPEG协议简介&quot;">​</a></h1><p>这一节的笔记我们来学习JPEG文件的格式。</p><h2 id="一、jpegsnoop" tabindex="-1">一、JPEGsnoop <a class="header-anchor" href="#一、jpegsnoop" aria-label="Permalink to &quot;一、JPEGsnoop&quot;">​</a></h2><h3 id="_1-简介" tabindex="-1">1. 简介 <a class="header-anchor" href="#_1-简介" aria-label="Permalink to &quot;1. 简介&quot;">​</a></h3><p>JPEGsnoop是一个详细的JPEG图像解码器和分析工具。它报告所有图像元数据，甚至可以帮助识别图像是否被编辑过。它有以下特点（这里我就没翻译了）：</p><ul><li>Decode JPEG, AVI (MJPG), PSD images</li><li>MCU analysis with detailed decode</li><li>Extract embedded JPEG images</li><li>Detect edited images through compression signature analysis</li><li>Report all image metadata (EXIF)</li><li>Batch file processing</li><li>Compression signature detection</li><li>Recover corrupt JPEG image data</li><li>No installation required</li></ul><p>官方Github仓库应该是这个：<a href="https://github.com/ImpulseAdventure/JPEGsnoop/" target="_blank" rel="noreferrer">GitHub - ImpulseAdventure/JPEGsnoop: JPEGsnoop: JPEG decoder and detailed analysis</a></p><h3 id="_2-下载与安装" tabindex="-1">2. 下载与安装 <a class="header-anchor" href="#_2-下载与安装" aria-label="Permalink to &quot;2. 下载与安装&quot;">​</a></h3><p>我们下载一下安装包，可以直接从发布版本中找：<a href="https://github.com/ImpulseAdventure/JPEGsnoop/releases" target="_blank" rel="noreferrer">Releases · ImpulseAdventure/JPEGsnoop (github.com)</a></p><img src="'+i+'" alt="image-20240725074043718" style="zoom:41%;"><p>我们直接下载第一个好了，下载后解压，可以得到这样一个文件：</p><img src="'+r+'" alt="image-20240725074226505" style="zoom:50%;"><p>这个软件是免安装的，直接双击打开即可。</p><img src="'+c+'" alt="image-20240725074328368" style="zoom:47%;"><p>我们打开一个jpeg文件看一下，我们这里就用之前自己生成的jpg文件，像素点少，后面可以更好的查看数据：</p><img src="'+t+'" alt="format-30x13"><p>打开后如下图所示：</p><img src="'+o+'" alt="image-20240725075107599" style="zoom:50%;"><h2 id="二、jpeg文件中段的概念" tabindex="-1">二、JPEG文件中段的概念 <a class="header-anchor" href="#二、jpeg文件中段的概念" aria-label="Permalink to &quot;二、JPEG文件中段的概念&quot;">​</a></h2><h3 id="_1-如何识别jpeg文件" tabindex="-1">1. 如何识别JPEG文件？ <a class="header-anchor" href="#_1-如何识别jpeg文件" aria-label="Permalink to &quot;1. 如何识别JPEG文件？&quot;">​</a></h3><p>我们平时是靠<code>.jpg</code>、<code>.jpeg</code>等后缀名来识别，看到这个后缀，我们就认为是一张JPEG图片，但是还是会有一些图片是没有后缀的，依然能被识别，这是怎么做的呢？</p><p>其实很简单，就是判断前面3个字节是什么，如果发现是FF D8 FF开始，那就认为它是JEPG图片。JPG文件是由一段段的数据构成的组成的（segment），段的多少和长度并不是一定的。只要包含了足够的信息，该JPEG文件就能够被打开。</p><h3 id="_2-段结构" tabindex="-1">2. 段结构 <a class="header-anchor" href="#_2-段结构" aria-label="Permalink to &quot;2. 段结构&quot;">​</a></h3><p>上面了解到JPEG 文件的格式是分为一个一个的段来存储的，段的多少和长度并不是一定的。只要包含了足够的信息，该JPEG文件就能够被打开，呈现给我们。接下来我们就开始学习一下段的相关基础知识。</p><p>JPEG文件的每个段都一定包含两部分：一个是段的标识，它由两个字节构成：第一个字节是十六进制0xFF，第二个字节对于不同的段，这个值是不同的。紧接着的两个字节存放的是这个段的长度（除了前面的两个字节0xFF和0xXX，X表示不确定。他们是不算到段的长度中的）。</p><p>注意：这个长度的表示方法是按照高位在前，低位在后的，与 Intel 的表示方法不同。比方说一个段的长度是0x12AB，那么它会按照0x12，0xAB的顺序存储。但是如果按照Intel的方式：高位在后，低位在前的方式会存储成0xAB，0x12，而这样的存储方法对于JPEG是不对的。这样的话如果一个程序不认识JPEG文件某个段，它就可以读取后两个字节，得到这个段的长度，并跳过忽略它。</p><p>段的一般结构如下：</p><img src="'+a+`" alt="image-20240726074235919"><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>-----------------------------------------------------------------</span></span>
<span class="line"><span>名称   字节数      数据     说明</span></span>
<span class="line"><span>-----------------------------------------------------------------</span></span>
<span class="line"><span>段标识   1         FF      每个新段的开始标识</span></span>
<span class="line"><span>段类型   1                 类型编码（称作“标记码”）</span></span>
<span class="line"><span>段长度   2                 包括段内容和段长度本身,不包括段标识和段类型</span></span>
<span class="line"><span>段内容                     ≤65533字节</span></span>
<span class="line"><span>————————————————</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>①JPG 文件中所有关于宽度高度长度间隔这一类数据，凡是＞１字节的，均采用Motorola格式，即：高位在前，低位在后。</p><p>②有些段没有长度描述也没有内容，只有段标识和段类型。文件头和文件尾均属于这种段。</p><p>③段与段之间无论有多少FF都是合法的，这些FF称为“填充字节”，必须被忽略掉。</p><h3 id="_3-段的标识与类型" tabindex="-1">3. 段的标识与类型 <a class="header-anchor" href="#_3-段的标识与类型" aria-label="Permalink to &quot;3. 段的标识与类型&quot;">​</a></h3><img src="`+a+`" alt="image-20240726074235919"><p>它由两个字节构成：第一个字节是段标识0xFF，第二个字节是段类型（对于不同的段是不同的），具体如下：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>段类型   表示符号      说明</span></span>
<span class="line"><span>——————————————————————————————————</span></span>
<span class="line"><span>SOI      D8          文件头(必须)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>APP0     E0          定义交换格式和图像识别信息(非必需)</span></span>
<span class="line"><span>APP1     E1          同上</span></span>
<span class="line"><span>....    ....         .... </span></span>
<span class="line"><span>APPn     En          同上</span></span>
<span class="line"><span></span></span>
<span class="line"><span>DQT      DB          定义量化表(必须)，量化操作会用到</span></span>
<span class="line"><span></span></span>
<span class="line"><span>SOF0     C0          图像基本信息，包含文件相关信息</span></span>
<span class="line"><span>SOF1     C1          同上</span></span>
<span class="line"><span>....    ....         ....</span></span>
<span class="line"><span>SOFn     Cn          同上</span></span>
<span class="line"><span></span></span>
<span class="line"><span>DHT      C4          定义 Huffman 表（霍夫曼表），熵编码的时候用</span></span>
<span class="line"><span>DRI      DD          定义重新开始间隔(非必需)</span></span>
<span class="line"><span>SOS      DA          扫描行开始，这个标志后面的数据为图像的数据，解码可得到图像信息</span></span>
<span class="line"><span></span></span>
<span class="line"><span>COM      FE          注释(非必需)</span></span>
<span class="line"><span>EOI      D9          文件尾</span></span>
<span class="line"><span>......</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br></div></div><p>段类型大概有30种，但上面那些是必须被所有程序识别的，其它的类型都可以忽略。</p><blockquote><p>常见的段：</p><ol><li>SOI（必须）：SOI段定义了文件头。该段仅有两个字节：FF D8，这两个字节代表了JPEG文件的开始。</li><li>APP0, APP1, APP2....（非必须）：APP0段定义了交换格式和图像识别信息。包含了一些像素和略缩图相关的信息。</li><li>DQT（必须）：DQT段定义了量化表。JPEG文件一般有两个DQT段，为亮度定义１个, 为色度定义１个。</li><li>SOF0, SOF1, SOF2....（必须）：SOF段定义了图像基本信息。包含了一些图片长宽高、组件等信息。</li><li>DHT（必须） ：DHT段定义了Huffman表，即霍夫曼编码表。</li><li>DRI（<strong>非必须</strong>）：DRI段定义了重新开始间隔，很多JPEG文件没有这个段。</li><li>SOS（必须）：SOS段定义了扫描行开始，紧接着SOS段后的就是一个个扫描行（压缩的图像数据）。</li><li>COM（<strong>非必须</strong>）：COM段定义了注释段，有的JPEG文件没有这个段。</li><li>EOI（必须）：EOI段定义了文件尾，该段仅有两个字节：FF D9，这两个字节代表了JPEG文件的结束。</li></ol></blockquote><h3 id="_4-段的长度" tabindex="-1">4. 段的长度 <a class="header-anchor" href="#_4-段的长度" aria-label="Permalink to &quot;4. 段的长度&quot;">​</a></h3><img src="`+a+`" alt="image-20240726074235919"><p>紧接着的两个字节存放的是这个段的长度（除了前面的两个字节0xFF和0xXX，X表示不确定。他们是不算到段的长度中的）。其作用是这样的话如果一个程序不认识JPEG文件某个段，它就可以读取后两个字节，得到这个段的长度，并跳过忽略它。</p><h2 id="三、一般有哪些段" tabindex="-1">三、一般有哪些段？ <a class="header-anchor" href="#三、一般有哪些段" aria-label="Permalink to &quot;三、一般有哪些段？&quot;">​</a></h2><h3 id="_1-soi-ffd8-——文件头" tabindex="-1">1. SOI(FFD8)——文件头 <a class="header-anchor" href="#_1-soi-ffd8-——文件头" aria-label="Permalink to &quot;1. SOI(FFD8)——文件头&quot;">​</a></h3><h4 id="_1-1-基本结构" tabindex="-1">1.1 基本结构 <a class="header-anchor" href="#_1-1-基本结构" aria-label="Permalink to &quot;1.1 基本结构&quot;">​</a></h4><p>JPEG文件的开始2个字节都是FF D8这是JPEG协议规定的：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>-----------------</span></span>
<span class="line"><span>名称  字节数 值</span></span>
<span class="line"><span>-----------------</span></span>
<span class="line"><span>段标识   1     FF</span></span>
<span class="line"><span>段类型   1     D8 </span></span>
<span class="line"><span>-----------------</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h4 id="_1-2-实例分析" tabindex="-1">1.2 实例分析 <a class="header-anchor" href="#_1-2-实例分析" aria-label="Permalink to &quot;1.2 实例分析&quot;">​</a></h4><p>我们可以打开之前准备的那个format-30x13.jpg文件看一下：</p><p><img src="`+b+'" alt="image-20240726074942254"></p><p>我们可以使用JPEGsnoop工具打开图片看一下：</p><img src="'+m+`" alt="image-20240727093445827" style="zoom:50%;"><h3 id="_2-app0-ffe0-——图像识别信息" tabindex="-1">2. APP0(FFE0)——图像识别信息 <a class="header-anchor" href="#_2-app0-ffe0-——图像识别信息" aria-label="Permalink to &quot;2. APP0(FFE0)——图像识别信息&quot;">​</a></h3><h4 id="_2-1-基本结构" tabindex="-1">2.1 基本结构 <a class="header-anchor" href="#_2-1-基本结构" aria-label="Permalink to &quot;2.1 基本结构&quot;">​</a></h4><p>APP0的基本结构如下：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>--------------------------------------------------------------------------</span></span>
<span class="line"><span>名称      字节数        值                   说明</span></span>
<span class="line"><span>--------------------------------------------------------------------------</span></span>
<span class="line"><span>段标识       1         FF</span></span>
<span class="line"><span>段类型       1         E0</span></span>
<span class="line"><span>段长度       2         00 10               如果有RGB缩略图就＝16＋3n</span></span>
<span class="line"><span></span></span>
<span class="line"><span>（以下为段内容）</span></span>
<span class="line"><span>交换格式      5        4A46494600          “JFIF”的ASCII码</span></span>
<span class="line"><span>主版本号      1</span></span>
<span class="line"><span>次版本号      1  </span></span>
<span class="line"><span>密度单位      1        0=无单位；1=点数/英寸；2=点数/厘米</span></span>
<span class="line"><span>X像素密度     2                             水平方向的密度   </span></span>
<span class="line"><span>Y像素密度     2                             垂直方向的密度</span></span>
<span class="line"><span>缩略图X像素   1                             缩略图水平像素数目  </span></span>
<span class="line"><span>缩略图Y像素   1                             缩略图垂直像素数目</span></span>
<span class="line"><span></span></span>
<span class="line"><span>（如果“缩略图X像素”和“缩略图Y像素”的值均＞0，那么才有下面的数据）</span></span>
<span class="line"><span>RGB缩略图    3×n      n＝缩略图像素总数＝缩略图X像素×缩略图Y像素</span></span>
<span class="line"><span>--------------------------------------------------------------------------</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br></div></div><p>（1）JFIF是JPEG File Interchange Forma的缩写，即JPEG文件交换格式，另外还有TIFF等格式，很少用。</p><p>（2）“如果有RGB缩略图就＝16＋3n”是什么意思呢？比如说“缩略图X像素”和“缩略图Y像素”的值均为48，就表示有一个48×48像素的缩略图（ｎ＝48×48），缩略图是24位真彩位图，用３个字节来表示一个像素，所以共占用3n个字节。但大多数JPG文件都没有这个“鸡肋”缩略图。</p><h4 id="_2-2-实例分析" tabindex="-1">2.2 实例分析 <a class="header-anchor" href="#_2-2-实例分析" aria-label="Permalink to &quot;2.2 实例分析&quot;">​</a></h4><img src="`+d+'" alt="image-20240727091512156"><p>（1）图像识别信息头：2个字节FF E0。</p><p>（2）段长度：00 10 也就是16个字节。</p><p>（3）交换格式5个字节：4A 46 49 46 00，此处代表‘JFIF’，一般我们用的都是JFIF的jpeg交换格式，但是也有TFIF的jpeg交换格式，如果camera sensor直接输出的是jpeg图片，那么在其sensor寄存器可以设置使用JFIF还是TFIF。</p><p>（4）主版本号和次版本号一共2个字节： 01 01 说明主版本号和此版本号都为1。</p><p>（5）单位密度1个字节：01 表示此处使用的是点数/英寸。</p><p>（6）X像素密度2个字节：00 a8表示水平像素密度是168。</p><p>（7）Y像素密度2个字节：00 a8表示垂直像素密度是168。</p><p>（8）缩略图X像素：00 表示没有缩略图。</p><p>（9）缩略图Y像素：00 表示没有缩略图。</p><p>（10）RGB缩略图：此处没有缩略图，所以是空的。</p><p>可以拿JPEGsnoop工具打开验证一下：</p><img src="'+u+`" alt="image-20240727093516502" style="zoom:67%;"><h3 id="_3-dqt-ffdb-——定义量化表" tabindex="-1">3. DQT(FFDB)——定义量化表 <a class="header-anchor" href="#_3-dqt-ffdb-——定义量化表" aria-label="Permalink to &quot;3. DQT(FFDB)——定义量化表&quot;">​</a></h3><h4 id="_3-1-基本结构" tabindex="-1">3.1 基本结构 <a class="header-anchor" href="#_3-1-基本结构" aria-label="Permalink to &quot;3.1 基本结构&quot;">​</a></h4><p>DQT，Define Quantization Table量化表：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>--------------------------------------------------------------------------</span></span>
<span class="line"><span>名称    字节数   值       说明</span></span>
<span class="line"><span>--------------------------------------------------------------------------</span></span>
<span class="line"><span>段标识    1     FF</span></span>
<span class="line"><span>段类型    1     DB</span></span>
<span class="line"><span>段长度    2     43       其值＝3+n（当只有一个QT时）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>（以下为段内容）</span></span>
<span class="line"><span>QT信息   1     [0:3]位：QT号 [4:7]位：QT精度（0=8bit，1字节；否则=16bit，2字节）</span></span>
<span class="line"><span>QT      n               n＝64×QT精度的字节数</span></span>
<span class="line"><span>--------------------------------------------------------------------------</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>（1）JPEG文件一般有２个DQT段，为Y值（亮度）定义１个, 为C值（色度）定义１个。</p><p>（2）一个DQT段可以包含多个QT， 每个都有自己的信息字节。QT一般是64/128Byte，精度为8位时64Byte，最多包含4个 表。</p><h4 id="_3-2-编码质量控制" tabindex="-1">3.2 编码质量控制 <a class="header-anchor" href="#_3-2-编码质量控制" aria-label="Permalink to &quot;3.2 编码质量控制&quot;">​</a></h4><p>使用不同的量化表可以对JPEG的编码质量进行控制：</p><img src="`+A+'" alt="image-20240729075256730" style="zoom:67%;"><h4 id="_3-3-实例分析" tabindex="-1">3.3 实例分析 <a class="header-anchor" href="#_3-3-实例分析" aria-label="Permalink to &quot;3.3 实例分析&quot;">​</a></h4><img src="'+h+'" alt="image-20240727104257900"><p>可以看到这里有两个量化表，此处有2个DQT数据，第一个是亮度的，第二个是色度的。以第一个亮度的为例：</p><p>（1）定义量化表的头2个字节：FF DB</p><p>（2）段长度2个字节：00 43就是3(段长度2个字节，QT信息1个字节)+QT量化表的长度，此处QT量化表的长度是64</p><p>（3）QT信息1个字节：以第一个量化表为例子00中0-3位是QT号，4-7位QT精度，此处是0，所以精度是8bit，即1个字节。以第二个量化表为例子 01就表示QT号是1，精度是8bit。</p><p>（4）QT量化表：这个的长度是根据QT信息确定的，上面QT精度为8bit，所以此处是64×1 = 64个字节 我们使用前面的JPEGsnoop工具打开看一下：</p><img src="'+g+`" alt="image-20240727093046246" style="zoom:67%;"><h3 id="_4-sof0-ffc0-——图像基本信息" tabindex="-1">4. SOF0(FFC0)——图像基本信息 <a class="header-anchor" href="#_4-sof0-ffc0-——图像基本信息" aria-label="Permalink to &quot;4. SOF0(FFC0)——图像基本信息&quot;">​</a></h3><h4 id="_4-1-基本结构" tabindex="-1">4.1 基本结构 <a class="header-anchor" href="#_4-1-基本结构" aria-label="Permalink to &quot;4.1 基本结构&quot;">​</a></h4><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>--------------------------------------------------------------------------</span></span>
<span class="line"><span>名称    字节数  值       说明</span></span>
<span class="line"><span>--------------------------------------------------------------------------</span></span>
<span class="line"><span>段标识    1     FF</span></span>
<span class="line"><span>段类型    1     C0</span></span>
<span class="line"><span>段长度    2             其值＝8＋组件数量×3</span></span>
<span class="line"><span></span></span>
<span class="line"><span>（以下为段内容）</span></span>
<span class="line"><span>样本精度  1      8       每个样本位数（大多数软件不支持12和16）</span></span>
<span class="line"><span>图片高度  2</span></span>
<span class="line"><span>图片宽度  2</span></span>
<span class="line"><span>组件数量  1      3       1＝灰度图，3＝YCbCr/YIQ 彩色图，4＝CMYK 彩色图</span></span>
<span class="line"><span></span></span>
<span class="line"><span>（以下每个组件占用３字节）</span></span>
<span class="line"><span>组件 ID  1               1＝Y, 2＝Cb, 3＝Cr, 4＝I, 5＝Q</span></span>
<span class="line"><span>采样系数  1               0－3位：垂直采样系数,4－7位：水平采样系数</span></span>
<span class="line"><span>量化表号  1</span></span>
<span class="line"><span>---------------------------------------------------------------------------</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br></div></div><p>（1）JPEG大都采用YCrCb色彩模型（Y表示亮度，Cr红色分量，Cb表示蓝色分量），所以组件数量一般＝3</p><p>（2）样本就是单个像素的颜色分量，也可理解为一个样本就是一个组件.</p><p>（3）采样系数是实际采样方式与最高采样系数之比，而最高采样系数一般＝0.5（分数表示为1/2）。比如说，垂直采样系数＝2，那么2×0.5＝1，表示实际采样方式是每个点采一个样，也就是逐点采样；如果垂直采样系数＝1，那么：1×0.5＝0.5（分数表示为1/2），表示每２个点采一个样</p><h4 id="_4-2-实例分析" tabindex="-1">4.2 实例分析 <a class="header-anchor" href="#_4-2-实例分析" aria-label="Permalink to &quot;4.2 实例分析&quot;">​</a></h4><img src="`+F+'" alt="image-20240727105201634"><p>（1）图像基本信息的：2个字节FF C0</p><p>（2）段长度2个字节：00 11 就是 17 = 8 + 3*3，说明组件数量有3个。</p><p>（3）样本精度1个字节：08，每个样本的信息是8bit。</p><p>（4）样本高度2个字节：00 0d = 13，图片高度与实际一致。</p><p>（5）样本宽度2个字节：00 1e = 30，图片宽度与实际一致。</p><p>（6）组件数量1个字节：03 代表YCbCr 彩色图，有3个组件分别是Y、Cb、Cr。</p><p>（7）每个组件占用3个字节：第一个字节是组件ID，第二个字节是采样系数，第三个字节是量化表号。此处是：</p><p>01 22 00 表示 Y组件，垂直采样系数和水平采样系数都是2，量化表号是0；02 11 01表示 Cb组件，垂直采样系数和水平采样系数都是1，量化表号是1；03 11 01表示 Cr组件，垂直采样系数和水平采样系数都是1，量化表号是1。此处可知此处Y采样是逐点采样，CbCr都是隔点采样，这就是标准的YUV422的数据。</p><img src="'+P+`" alt="image-20240727105617732" style="zoom:50%;"><h3 id="_5-dht-ffc4-——定义huffman表" tabindex="-1">5. DHT(FFC4)——定义huffman表 <a class="header-anchor" href="#_5-dht-ffc4-——定义huffman表" aria-label="Permalink to &quot;5. DHT(FFC4)——定义huffman表&quot;">​</a></h3><h4 id="_5-1-基本结构" tabindex="-1">5.1 基本结构 <a class="header-anchor" href="#_5-1-基本结构" aria-label="Permalink to &quot;5.1 基本结构&quot;">​</a></h4><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>--------------------------------------------------------------------------</span></span>
<span class="line"><span>名称    字节数   值       说明</span></span>
<span class="line"><span>--------------------------------------------------------------------------</span></span>
<span class="line"><span>段标识    1     FF</span></span>
<span class="line"><span>段类型    1     C4</span></span>
<span class="line"><span>段长度    2              其值＝19＋n（当只有一个HT表时）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>（以下为段内容）</span></span>
<span class="line"><span>HT信息   1               [0:3]位:HT号; [4]位:HT类型, 0＝DC表，1＝AC表; [5:7]位：必须＝0</span></span>
<span class="line"><span>HT位表   16              这16个数的和应该≤256，分别表示1-16bit位数码字的数量</span></span>
<span class="line"><span>HT值表   n               n＝表头16个数的和</span></span>
<span class="line"><span>--------------------------------------------------------------------------</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p>（1）JPEG文件里有２类Haffman 表：一类用于DC（直流量），一类用于AC（交流量）。一般有４个表：亮度的DC和AC，色度的DC和AC，最多可有６个。</p><p>（2）一个DHT 段可以包含多个HT表, 每个都有自己的信息字节</p><p>（3）HT表是一个按递增次序代码长度排列的符号表。</p><h4 id="_5-2-实例分析" tabindex="-1">5.2 实例分析 <a class="header-anchor" href="#_5-2-实例分析" aria-label="Permalink to &quot;5.2 实例分析&quot;">​</a></h4><img src="`+C+'" alt="image-20240728093412783"><p>（1）定义Huffman表头2个字节：FF C4</p><p>（2）段长度2个字节：以①为例子 00 1F就是31 = 19(段长度2个字节+HT信息1个字节+HT位表16个字节) + 12(这个数代表HT表有12个字节)</p><p>（3）HT信息1个字节：[0:3]位是HT号，[4]位是HT类型(0=DC表，1＝AC表)，[5:]7位必须为0。①中 00 表示 HT号是0，DC表；②中 10 表示 HT号是0，AC表；以③为例子 01 表示 HT号是1，DC表；④中 11表示 HT号是1，AC表。此处一共有4个Haffman 表，亮度DC Haffman 表，亮度AC Haffman 表，色度DC Haffman 表，色度AC Haffman 表</p><p>（4）HT位表16个字节：这16个数字值和小于等于256。①中 00 01 05 01 01 01 01 01 01 00 00 00 00 00 00 00 共16个字节，加起来是12(此处和段长度是相匹配的)，说明HT表有12个字节。</p><p>（5）HT值表：以①为例子00 01 02 03 04 05 06 07 08 09 0A 0B。</p><p>我们使用JPEGsnoop工具打开看一下，</p><img src="'+f+`" alt="image-20240728093813473" style="zoom:50%;"><h3 id="_6-sos-ffda-——扫描行开始" tabindex="-1">6. SOS(FFDA)——扫描行开始 <a class="header-anchor" href="#_6-sos-ffda-——扫描行开始" aria-label="Permalink to &quot;6. SOS(FFDA)——扫描行开始&quot;">​</a></h3><h4 id="_6-1-基本结构" tabindex="-1">6.1 基本结构 <a class="header-anchor" href="#_6-1-基本结构" aria-label="Permalink to &quot;6.1 基本结构&quot;">​</a></h4><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>--------------------------------------------------------------------------</span></span>
<span class="line"><span>名称            字节数    值       说明</span></span>
<span class="line"><span>--------------------------------------------------------------------------</span></span>
<span class="line"><span>段标识            1      FF</span></span>
<span class="line"><span>段类型            1      DA</span></span>
<span class="line"><span>段长度            2      000C    其值＝6＋2×扫描行内组件数量</span></span>
<span class="line"><span></span></span>
<span class="line"><span>（以下为段内容）</span></span>
<span class="line"><span>扫描行内组件数量    1      3       必须≥1，≤4（否则错误），通常＝3</span></span>
<span class="line"><span></span></span>
<span class="line"><span>（以下每个组件占用２字节）</span></span>
<span class="line"><span>组件ID            1     1 = Y, 2 = Cb, 3 = Cr, 4 = I, 5 = Q</span></span>
<span class="line"><span>Huffman表号       1              [0:3]位：AC表号 (其值＝0...3); [4:7]位：DC表号(其值＝0...3)</span></span>
<span class="line"><span>剩余3个字节        3              最后３个字节用途不明，忽略</span></span>
<span class="line"><span>--------------------------------------------------------------------------</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br></div></div><p>紧接SOS段后的是压缩的图像数据（一个个扫描行），数据存放顺序是从左到右、从上到下。</p><h4 id="_6-2-扫描数据格式" tabindex="-1">6.2 扫描数据格式 <a class="header-anchor" href="#_6-2-扫描数据格式" aria-label="Permalink to &quot;6.2 扫描数据格式&quot;">​</a></h4><p>扫描数据按照MCU顺序存储，当编码后数据出现0xFF时，为了避免与JPEG关键字冲突，需要在其后补充0x00，即每个单字节0xFF会存储为0xFF00两个字节。</p><p>当JPEG文件支持DRI，则需要按照DRI的值，每隔该值指示的周期，MCU内的直流分量重新开始差分计算，同时需要在周期结束的数据后面增加RSTn(0xFFD0-D7)标记，标记循环添加，不能跳过。最后一个周期结束为0xFFD9不需要添加RSTn。</p><p>由DRI指示的多个MCU构成一个slice，一个slice的数据可以独立解码。</p><p>当一个周期结束时，此时写入的bit数据不满一个字节时，需要将剩余字节填充为1b。</p><h4 id="_6-3-实例分析" tabindex="-1">6.3 实例分析 <a class="header-anchor" href="#_6-3-实例分析" aria-label="Permalink to &quot;6.3 实例分析&quot;">​</a></h4><img src="`+D+'" alt="image-20240728095450833"><p>（1）扫描行开始的头，2个字节：FF DA</p><p>（2）段长度2个字节：00 0C 就是 12 = 6(2个字节的扫描行开始头+1个字节扫描行内组件数量+3个字节的剩余位) + 2×3(扫描行内组件数量，每个组件2个字节)</p><p>（3）扫描行内组件数量1个字节：03 代表组件数量数3</p><p>（4）每个组件占用2个字节：第一个字节是组件ID(1 = Y, 2 = Cb, 3 = Cr, 4 = I, 5 = Q)；第二个字节[0:3]位AC表号，[4:7]位DC表号。表号的值是0-3。01 00 表示 Y组件，AC表号是0，DC表号是0；02 11表示 Cb组件，AC表号是1，DC表号是1；03 11 表示 Cr组件，AC表号是1，DC表号是1。此处跟DHT（定义Huffman表）的HT信息是一致的。</p><img src="'+E+`" alt="image-20240728101513739" style="zoom:67%;"><h3 id="_7-eoi-ffd9-——文件尾" tabindex="-1">7. EOI(FFD9)——文件尾 <a class="header-anchor" href="#_7-eoi-ffd9-——文件尾" aria-label="Permalink to &quot;7. EOI(FFD9)——文件尾&quot;">​</a></h3><h4 id="_7-1-基本结构" tabindex="-1">7.1 基本结构 <a class="header-anchor" href="#_7-1-基本结构" aria-label="Permalink to &quot;7.1 基本结构&quot;">​</a></h4><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>------------------</span></span>
<span class="line"><span>名称  字节数   值</span></span>
<span class="line"><span>------------------</span></span>
<span class="line"><span>段标识   1     FF</span></span>
<span class="line"><span>段类型   1     D9 </span></span>
<span class="line"><span>------------------</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h4 id="_7-2-实例分析" tabindex="-1">7.2 实例分析 <a class="header-anchor" href="#_7-2-实例分析" aria-label="Permalink to &quot;7.2 实例分析&quot;">​</a></h4><img src="`+I+'" alt="image-20240728101645437"><p>这个就没啥好说的了，就在文件结尾。</p><img src="'+J+`" alt="image-20240728101719062" style="zoom:67%;"><h3 id="_8-dri-ffdd-——定义重新开始间隔" tabindex="-1">8. DRI(FFDD)——定义重新开始间隔 <a class="header-anchor" href="#_8-dri-ffdd-——定义重新开始间隔" aria-label="Permalink to &quot;8. DRI(FFDD)——定义重新开始间隔&quot;">​</a></h3><h4 id="_8-1-基本结构" tabindex="-1">8.1 基本结构 <a class="header-anchor" href="#_8-1-基本结构" aria-label="Permalink to &quot;8.1 基本结构&quot;">​</a></h4><p>DRI, Define Restart Interval，复位的间隔：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>--------------------------------------------------------------------------</span></span>
<span class="line"><span>名称    字节数   值   说明</span></span>
<span class="line"><span>--------------------------------------------------------------------------</span></span>
<span class="line"><span>段标识    1     FF</span></span>
<span class="line"><span>段类型    1     DD</span></span>
<span class="line"><span>段长度    2     4 </span></span>
<span class="line"><span></span></span>
<span class="line"><span>（以下为段内容）</span></span>
<span class="line"><span>开始间隔   2     n   复位标记的间隔距离</span></span>
<span class="line"><span>---------------------------------------------------------------------------</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><p>（1）开始间隔表示在压缩数据流中，每隔 n 个MCU 块就有一个RST标记，RST标记将Huffman 的解码数据流复位，DC也重新从0开始，因此，RST标记是一种复位标记。（表示每隔多少个MCU 重置一次差分编码值，一组MCU称为一个slice，可独立解码， 多个slice之间通过RSTn进行分割）。</p><blockquote><p>&quot;DC从0开始&quot;的含义：DC（直流分量）代表每个8×8图像块的平均亮度值。JPEG编码时，为了压缩数据，通常会使用差分编码来记录当前块与前一块DC值的差值，而不是记录绝对值。当遇到RST标记时，这种差分编码的累积计算会被重置。&quot;DC重新从0开始&quot;是指重新开始计算差分编码的基准点，即下一个图像块的DC值将直接记录其实际值（或与重置后的基准的差值），而不是延续之前的差分计算链。</p><p>这样做的好处：如果数据传输或解码过程中出现错误（如网络丢包、文件损坏），解码器可以通过 RSTn 标记快速重同步。遇到错误时，解码器只需跳转到下一个 RSTn 标记继续解码，避免错误扩散到整个图像。由于 RSTn 标记之间的数据段相互独立，解码器可以同时处理多个段，提升解码效率（尤其在多核处理器中）。</p></blockquote><p>（2）RST 标记是一种特殊的段，它只具有段标识和段类型（长度＝２字节），但它不是独立的段，只能穿插在数据流中（文件头和文件尾段也只有段标识和段类型，却都是独立的段）。</p><p>（3）RST标记共有８个（RST0－RST7），从RST0起开始使用，然后是RST1….直至RST7，再从RST0重复。</p><p>（4）RST标记的标识码是 FFD0－FFD7，对应 RST0－RST7。</p><blockquote><p>说明：这个不是必须段，很多JPEG都没有。</p></blockquote><h4 id="_8-2-实例分析" tabindex="-1">8.2 实例分析 <a class="header-anchor" href="#_8-2-实例分析" aria-label="Permalink to &quot;8.2 实例分析&quot;">​</a></h4><p>之前用的jpg图片没有这个信息，网上找了个，但是只有截图，没见原图，这里参考一下好啦：</p><img src="`+T+'" alt="image-20240728102229429"><h2 id="四、jpeg标准与文件格式" tabindex="-1">四、JPEG标准与文件格式 <a class="header-anchor" href="#四、jpeg标准与文件格式" aria-label="Permalink to &quot;四、JPEG标准与文件格式&quot;">​</a></h2><p>我们重新看一下JPEG的概念：JPEG是联合图象专家组(Joint Picture Expert Group)的英文缩写，是国际标准化组织(ISO)和CCITT联合制定的静态图象的<strong>压缩编码标准</strong>。</p><p>我们通常说的JPEG指的是以JPEG格式压缩的图片(即文件后缀为<code>.jpeg</code> <code>.jpe</code> )。经过JPEG重新编码的图片，文件压缩率可以达到90%以上，而且图片本身还具有较好的图片质量。这也是JPEG成为目前互联网上被用来存储和传输图片应用最广泛的格式的一个重要原因。</p><p>JPEG本身只有描述如何将一个视频/图片转换为字节的数据流（streaming），但并没有说明这些字节如何在任何特定的存储媒体上被封存起来。</p><p>很多人会把JPEG标准和JPEG文件格式理解成一个东西。然而实际并不是这样的，JPEG标准主要还是围绕编解码的部分（如DCT变换、量化、哈夫曼树等等），虽然在JPEG标准中也定义了“<strong>JPEG Interchange Format (JIF)</strong>”的文件存储格式，但是因为Encoder和Decoder完整实现 JIF 很困难，且 JIF 标准也存在一些缺陷，因此JIF并没有被推广开来。倒是后来出现的“<strong>JPEG File Interchange Format</strong> (JFIF)” 和 “**Exchange image file Format(**Exif)” 等新的存储格式成为了主流。Exif 也好 JFIF 也罢，他们都是遵循 JIF 标准的，两者只是在 JIF 的基础上增加了一些各自的Marker。</p><ul><li><strong>JPEG是压缩标准，JPEG/JFIF和JPEG/Exif是文件格式标准</strong>，不是一个概念，需要注意区分。</li><li>JPEG/Exif文件格式标准是Camera产业联合会发布，主要用于摄像设备上，摄像产业把Exif作为行业的元数据（metadata)交换格式</li><li>JPEG/JFIF文件格式标准是为了方便JPEG压缩图像在广泛的平台和应用间以最小的存储空间代价进行交换而设计的，它不包含JPEG/TIFF标准任何高级特性。</li></ul><p>上面学习JPEG中段的概念的时候，实例使用的就是一张符合JFIF格式标准的jpg图片。</p><h2 id="五、多slice拼接" tabindex="-1">五、多Slice拼接 <a class="header-anchor" href="#五、多slice拼接" aria-label="Permalink to &quot;五、多Slice拼接&quot;">​</a></h2><img src="'+k+'" alt="image-20240730073730286" style="zoom:50%;"><blockquote><p>参考资料：</p><p><a href="https://www.ijg.org/files/T-REC-T.871-201105-I!!PDF-E.pdf" target="_blank" rel="noreferrer">ITU-T Rec. T.871 (05/2011) Information technology - Digital compression and coding of continuous-tone still images: JPEG File Interchange Format (JFIF)</a></p></blockquote>',166)])])}const B=n(G,[["render",Q]]);export{_ as __pageData,B as default};
